<script>
(()=>{if(window.__giftchetaCatalogColumns)return;window.__giftchetaCatalogColumns=true;function setColumns(value,updateUrl=true){const columns=Math.max(1,Math.min(4,Number(value)||4)),grid=document.querySelector('.catalog-results .product-grid');if(grid)grid.dataset.columns=String(columns);document.querySelectorAll('[data-catalog-columns]').forEach(button=>{const active=Number(button.dataset.catalogColumns)===columns;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});const hidden=document.querySelector('[data-live-catalog-filters] input[name="columns"]');if(hidden)hidden.value=String(columns);if(updateUrl){const url=new URL(location.href);url.searchParams.set('columns',String(columns));url.searchParams.delete('page');history.pushState({},'',url.pathname+url.search)}}document.addEventListener('click',event=>{const button=event.target.closest('[data-catalog-columns]');if(button)setColumns(button.dataset.catalogColumns)});window.addEventListener('popstate',()=>{const columns=Number(new URL(location.href).searchParams.get('columns'))||4;setColumns(columns,false)});})();
</script>
